def calc(expr: str) -> int | str:
    n = len(expr)
    pos = 0

    def skip_ws() -> None:
        nonlocal pos
        while pos < n and expr[pos].isspace():
            pos += 1

    def parse_expr() -> int:
        nonlocal pos
        val = parse_term()
        while True:
            skip_ws()
            if pos < n and expr[pos] == "+":
                pos += 1
                val += parse_term()
            elif pos < n and expr[pos] == "-":
                pos += 1
                val -= parse_term()
            else:
                return val

    def parse_term() -> int:
        nonlocal pos
        val = parse_unary()
        while True:
            skip_ws()
            if pos < n and expr[pos] in "*/%":
                op = expr[pos]
                pos += 1
                rhs = parse_unary()
                if op == "*":
                    val *= rhs
                elif op == "/":
                    if rhs == 0:
                        raise ZeroDivisionError
                    q = abs(val) // abs(rhs)
                    val = -q if (val < 0) != (rhs < 0) else q
                else:
                    if rhs == 0:
                        raise ZeroDivisionError
                    r = abs(val) % abs(rhs)
                    val = -r if val < 0 else r
            else:
                return val

    def parse_unary() -> int:
        nonlocal pos
        chain: list[tuple[bool, int]] = []
        while True:
            neg = False
            while True:
                skip_ws()
                if pos < n and expr[pos] == "-":
                    neg = not neg
                    pos += 1
                else:
                    break
            base = parse_primary()
            chain.append((neg, base))
            skip_ws()
            if pos < n and expr[pos] == "^":
                pos += 1
                continue
            break

        neg, acc = chain.pop()
        if neg:
            acc = -acc
        while chain:
            neg, base = chain.pop()
            if acc < 0:
                raise ValueError
            acc = base ** acc
            if neg:
                acc = -acc
        return acc

    def parse_primary() -> int:
        nonlocal pos
        skip_ws()
        if expr[pos] == "(":
            pos += 1
            val = parse_expr()
            skip_ws()
            pos += 1
            return val
        start = pos
        while pos < n and "0" <= expr[pos] <= "9":
            pos += 1
        if pos - start <= 4000:
            return int(expr[start:pos])
        val = 0
        i = start
        while i < pos:
            end = min(i + 4000, pos)
            val = val * (10 ** (end - i)) + int(expr[i:end])
            i = end
        return val

    try:
        return parse_expr()
    except (ZeroDivisionError, ValueError):
        return "error"
